855	    public static BigDecimal lateCharge(Claim claim, BigDecimal figure, Sheet sheet, String grade) {
856	        BigDecimal none = BigDecimal.ZERO.setScale(2);
857	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(sheet.getToday())) {
858	            return none;
859	        }
860	        return lateChargeAsOpen(claim, figure, sheet, grade);
861	    }
862	
863	    /** The late charge a claim would have gained on its figure by the sheet's today were it still open. */
864	    private static BigDecimal lateChargeAsOpen(Claim claim, BigDecimal figure, Sheet sheet, String grade) {
865	        BigDecimal none = BigDecimal.ZERO.setScale(2);
866	        if (figure == null || claim.isCorrection()) {
867	            return none;
868	        }
869	        LocalDate from = overdueFrom(claim, sheet, grade);
870	        long periods = ChronoUnit.DAYS.between(from, sheet.getToday()) / 30;
871	        RoundingMode rounding = sheet.roundingFor(claim.getDate());
872	        BigDecimal charge = none;
873	        for (long k = 1; k <= periods; k++) {
874	            charge = charge.add(dueOn(figure.add(charge), sheet.latePctOn(from.plusDays(30 * k)), rounding));
875	        }
876	        return charge;
877	    }
878	
879	    /** A claim's live figure at a rate: its due on its amount, rounded as the claim rounds. The floor is not applied
880	     *  to it: it is applied last, to the figure with its late charge (see {@link #floored(Claim, BigDecimal, Sheet)}). */
881	    public static BigDecimal liveFigure(Claim claim, BigDecimal rate, RoundingMode rounding) {
882	        return dueOn(claim.getAmount(), rate, rounding);
883	    }
884	
885	    /** A claim's due (its figure with its late charge) raised to the floor in force on its date, unless it is a
886	     *  correction. */
887	    public static BigDecimal floored(Claim claim, BigDecimal due, Sheet sheet) {
888	        return due == null || claim.isCorrection() || sheet == null ? due : floored(due, sheet.floorOn(claim.getDate()));
889	    }
890	
891	    /** A live due raised to the sheet's floor when it is below it. */
892	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
893	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
894	    }
895	
896	    /** The terms in days a claim of the person dated {@code date} is due by: the person's own, else their grade's
897	     *  in force then, else the sheet's then. */
898	    private static int termsOf(Sheet sheet, Person person, LocalDate date) {
899	        return person.getTerms() != null ? person.getTerms() : sheet.termsFor(person.gradeOn(date), date);
900	    }
901	
902	    private static BigDecimal scaled(BigDecimal amount) {
903	        return amount.setScale(2, RoundingMode.UNNECESSARY);
904	    }
905	
906	    /** An external reference as kept: trimmed, none when blank. */
907	    public static String refOf(String ref) {
908	        return ref == null || ref.isBlank() ? null : ref.trim();
909	    }
910	
911	    /** Tags as kept: each trimmed and lower-cased, blanks and repeats dropped, sorted and joined by commas; none
912	     *  when there are none. */
913	    public static String tagsOf(String tags) {
914	        if (tags == null) {
915	            return null;
916	        }
917	        String joined = String.join(",", new TreeSet<>(Arrays.stream(tags.split(","))
918	                .map(t -> t.trim().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty()).toList()));
919	        return joined.isEmpty() ? null : joined;
920	    }
921	
922	    /** The refusal of an external reference already used on the sheet. */
923	    public static ResponseStatusException refUsed(String ref) {
924	        return new ResponseStatusException(HttpStatus.CONFLICT, "The reference " + ref + " is already used on this sheet");
925	    }
926	
927	    private static String noteOf(String note) {
928	        return note == null ? "" : note.trim();
929	    }
930	}

