    public Map<Long, BigDecimal> dueByPersonBetween(String sheetId, LocalDate from, LocalDate to) {
        List<Rate> sheetRates = rates.findBySheetId(sheetId);
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        Map<Long, Person> personOf = new LinkedHashMap<>();
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        people.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> {
            personOf.put(p.getId(), p);
            totals.put(p.getId(), BigDecimal.ZERO.setScale(2));
        });
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        for (Claim claim : sheetClaims) {
            Person person = personOf.get(claim.getPersonId());
            if (person == null || !person.countsAtEnd(claim, to, today) || claim.isDeferredOn(today) || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)) {
                continue;
            }
            BigDecimal due = dueOf(claim, person.gradeOn(claim.getDate()), sheetRates, sheet, sheetClaims);
            if (due != null) {
                totals.merge(person.getId(), due, BigDecimal::add);
            }
        }
        return totals;
    }

    /** What a candidate rate would change: how many claims would show a different due, and the sum of the
     *  differences (new due minus current due), with two decimals. */
    public record RatePreview(int count, String diff) {
    }

    /** How the OPEN and PENDING claims of people on a grade (in force on each claim's date) would change were a rate
     *  to apply to that grade on every date: a claim bound by a statement does not change and a settled one is not
     *  counted; a due of none counts as 0 in the sum. Nothing is stored. */
    public RatePreview preview(String sheetId, String grade, BigDecimal rate) {
        List<Rate> sheetRates = rates.findBySheetId(sheetId);
        List<Rate> candidate = Stream.concat(sheetRates.stream().filter(r -> !r.getGrade().equals(grade)),
                Stream.of(new Rate(sheetId, grade, null, rate.setScale(2, RoundingMode.UNNECESSARY)))).toList();
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        Map<Long, Person> personOf = new LinkedHashMap<>();
        people.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> personOf.put(p.getId(), p));
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        int count = 0;
        BigDecimal diff = BigDecimal.ZERO.setScale(2);
        for (Claim claim : sheetClaims) {
            Person person = personOf.get(claim.getPersonId());
            if (person == null || claim.getSettledDue() != null
                    || (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING)
                    || !grade.equals(person.gradeOn(claim.getDate()))) {
                continue;
            }
            BigDecimal now = dueOf(claim, grade, sheetRates, sheet, sheetClaims);
            BigDecimal then = dueOf(claim, grade, candidate, sheet, sheetClaims);
            if (!Objects.equals(now, then)) {
                count++;
                diff = diff.add(then == null ? BigDecimal.ZERO : then)
                        .subtract(now == null ? BigDecimal.ZERO : now);
            }
        }
        return new RatePreview(count, diff.setScale(2).toPlainString());
    }

    /**
     * Record, once the change commits, how the sheet's figures moved since {@code before}: a ROLLUP line
     * for each person whose figures changed (one who did not exist before counting as changed), then a
     * TOTALS line if the sheet's totals changed. Nothing is recorded when no figure moved.
     */
    public void recordChanges(String sheetId, String user, Figures before) {
        Figures after = of(sheetId);
        after.people().forEach((id, figures) -> {
            PersonFigures was = before.people().get(id);
            if (was == null || !was.claimed().equals(figures.claimed()) || !was.dueTotal().equals(figures.dueTotal())
                    || !was.overdueTotal().equals(figures.overdueTotal())) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal()
                        + " overdue-total=" + figures.overdueTotal());
            }
        });
        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
                || !before.overdueTotal().equals(after.overdueTotal())) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
    }

    /** The rates of one grade among a sheet's. */
    private static List<Rate> ratesOf(List<Rate> sheetRates, String grade) {
        return sheetRates.stream().filter(r -> r.getGrade().equals(grade)).toList();
    }

    /** A claim's due: its settled figure, else its stated one (none while PENDING), else its amount at the rate in force on its date of
     *  its person's grade in force on that date, rounded as the claim rounds (by the sheet's policy date); an overdue claim's late charge is added on top of the figure, and the
     *  sum is raised to the floor in force on its date unless it is a correction. */
    private static BigDecimal dueOf(Claim claim, String grade, List<Rate> sheetRates, Sheet sheet, List<Claim> sheetClaims) {
        List<Rate> gradeRates = ratesOf(sheetRates, grade);
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN
                : sheet.roundingFor(ClaimService.roundingDate(claim, sheetClaims));
        BigDecimal figure = claim.isBound() ? claim.getBoundDue()
                : Rate.inForceOn(gradeRates, claim.getDate())
                        .map(rate -> ClaimService.liveFigure(claim, rate.getRate(), rounding))
                        .orElse(null);
        return figure == null || sheet == null ? figure
                : ClaimService.floored(claim, figure.add(ClaimService.lateCharge(claim, figure, sheet, grade)), sheet);
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet: a name and a grade (A, B or C), dated: each grade is in force from its from-date. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades recorded for the person; the first given has no from-date (from the beginning of time). */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<GradeFrom> grades = new ArrayList<>();

    /** The person's own terms in days, ahead of their grade's and the sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The person's holds: their open claims dated within one, and not bound by a statement, count in no live
     *  total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<Hold> holds = new ArrayList<>();

    /** Raised on every save; an edit made from an older version is refused. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new GradeFrom(null, grade));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grades recorded, in the order they take effect. */
    public List<GradeFrom> getGrades() {
        return grades.stream().sorted(GradeFrom.BY_FROM).toList();
    }

    /** The grade in force on {@code date}: the one with the latest from-date on or before it. A null date
     *  takes the latest grade recorded. */
    public String gradeOn(LocalDate date) {
        return grades.stream()
                .filter(g -> date == null || g.getFromDate() == null || !g.getFromDate().isAfter(date))
                .max(GradeFrom.BY_FROM)
                .orElseGet(() -> grades.stream().min(GradeFrom.BY_FROM).orElseThrow())
                .getGrade();
    }

    /** Record {@code grade} from {@code from}, replacing the grade recorded from that same date, if any. */
    public void setGradeFrom(LocalDate from, String grade) {
        grades.removeIf(g -> Objects.equals(g.getFromDate(), from));
        grades.add(new GradeFrom(from, grade));
    }

    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    public long getVersion() {
        return version;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Retired as soon as a retirement date is set, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** The holds recorded, in the order they start. */
    public List<Hold> getHolds() {
        return holds.stream().sorted(Hold.BY_FROM).toList();
    }

    public void addHold(Hold hold) {
        holds.add(hold);
    }

    /** Whether a claim of this person counts in the live totals on the sheet's {@code today}: an OPEN or PENDING one
     *  dated within a hold, or any once {@code today} reaches the retirement date, does not, unless a statement
     *  binds it. */
    public boolean counts(Claim claim, LocalDate today) {
        return claim.getStatus().counts() && (claim.isStated() || !heldOn(claim, today));
    }

    /** Whether a claim of this person counts in the figures of a period ending {@code end}: by the status it had at
     *  the end of that day, left out when held or retired as the live totals on the sheet's {@code today} say. */
    public boolean countsAtEnd(Claim claim, LocalDate end, LocalDate today) {
        ClaimStatus at = claim.statusAt(end);
        return at != null && at.counts() && (claim.isStated() || !heldOn(claim, today));
    }

    /** Whether a claim of this person counts when no statement binds it, as a new statement finds it. */
    public boolean countsUnbound(Claim claim, LocalDate today) {
        return claim.getStatus().counts() && !heldOn(claim, today);
    }

    /** Whether the claim is open and dated within one of the person's holds, or open once {@code today} reaches
     *  the person's retirement date. */
    private boolean heldOn(Claim claim, LocalDate today) {
        return claim.getStatus().isOpen()
                && (retiredOn(today) || holds.stream().anyMatch(h -> h.covers(claim.getDate())));
    }

    /** Whether the retirement date is reached on {@code date}: set, and on or before it. */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date != null && !date.isBefore(retiredFrom);
    }

    /** Whether a claim dated {@code date} is refused: one dated after the retirement date. */
    public boolean refusesClaimOn(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;
import java.util.Comparator;

/** A hold on a person from its from-date to its to-date, both inclusive; a null to-date does not end. */
@Embeddable
public class Hold {

    /** Orders holds by the date they start. */
    public static final Comparator<Hold> BY_FROM = Comparator.comparing(Hold::getFromDate);

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected Hold() {
    }

    public Hold(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** Whether {@code date} is within the hold. */
    public boolean covers(LocalDate date) {
        return !date.isBefore(fromDate) && (toDate == null || !date.isAfter(toDate));
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;
import java.util.Comparator;

/** A grade a person has from a date until their next one's; a null from-date is from the beginning of time. */
@Embeddable
public class GradeFrom {

    /** Orders grades by the date they take effect, the one from the beginning of time first. */
    public static final Comparator<GradeFrom> BY_FROM =
            Comparator.comparing(GradeFrom::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder()));

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "grade", nullable = false)
    private String grade;

    protected GradeFrom() {
    }

    public GradeFrom(LocalDate fromDate, String grade) {
        this.fromDate = fromDate;
        this.grade = grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public String getGrade() {
        return grade;
    }
}

