package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** A period of a sheet: a name unique on the sheet, from and to dates inclusive. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    /** Whether the period is closed: no claim dated inside it can then be added, edited or moved. */
    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether the period is soft-closed: its figures are fixed as for a close, but claims dated inside it can still
     *  be added and changed. Never set together with closed. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** The period's due-total fixed when it was closed or soft-closed; none while it is open. */
    @Column(name = "closed_total", precision = 14, scale = 2)
    private BigDecimal closedTotal;

    /** Each person's due-total for the period, by person id, fixed when it was closed or soft-closed; empty while it
     *  is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "due_total", nullable = false, precision = 14, scale = 2)
    private Map<Long, BigDecimal> closedPersonTotals = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    /** Whether a date falls inside this period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(fromDate) && !date.isAfter(toDate);
    }

    /** Whether this period shares a day with the period from {@code from} to {@code to}. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !fromDate.isAfter(to) && !from.isAfter(toDate);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getClosedPersonTotals() {
        return Map.copyOf(closedPersonTotals);
    }

    /** Close the period, fixing each person's due-total for it; its own is their sum. */
    public void close(Map<Long, BigDecimal> personTotals) {
        fix(personTotals);
        this.closed = true;
    }

    /** Soft-close the period, fixing each person's due-total for it as a close does, but leaving its claims open to
     *  change. */
    public void softClose(Map<Long, BigDecimal> personTotals) {
        fix(personTotals);
        this.softClosed = true;
    }

    private void fix(Map<Long, BigDecimal> personTotals) {
        this.closed = false;
        this.softClosed = false;
        this.closedPersonTotals.clear();
        this.closedPersonTotals.putAll(personTotals);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.closedPersonTotals.clear();
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The periods of a sheet. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final Audit audit;
    private final Rollup rollup;
    private final RoleService roles;

    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetStore, Audit audit,
            Rollup rollup, RoleService roles) {
        this.roles = roles;
        this.periods = periods;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** The sheet's periods, by from-date. */
    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    /** Add a period; the name is stored trimmed. Refused when the name is in use on the sheet, the
     *  to-date is before the from-date, or it shares a day with another period of the sheet. With no
     *  from-date it starts on the sheet's today. */
    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate fromDate, LocalDate to) {
        sheets.load(sheetId, user);
        // The sheet is locked so two periods added at the same moment cannot overlap.
        LocalDate today = sheetStore.findLockedById(sheetId).orElseThrow().getToday();
        LocalDate from = fromDate != null ? fromDate : today;
        String trimmed = name.trim();
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts");
        }
        List<Period> existing = periods.findBySheetIdOrderByFromDateAsc(sheetId);
        if (existing.stream().anyMatch(p -> p.getName().equals(trimmed))) {
            throw nameInUse();
        }
        if (existing.stream().anyMatch(p -> p.overlaps(from, to))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another on this sheet");
        }
        Period added;
        try {
            added = periods.saveAndFlush(new Period(sheetId, trimmed, from, to));
        } catch (DataIntegrityViolationException raced) {
            throw nameInUse();
        }
        audit.recordChangeOnCommit(sheetId, user, "PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName()
                + " from=" + added.getFromDate() + " to=" + added.getToDate());
        return added;
    }

    /** Generate one period per calendar month from the from-date's month to the to-date's month, each running
     *  from the first to the last day of its month and named yyyy-mm. A month whose name is already a period, or
     *  whose days overlap a period of the sheet, is left out. Refused when the to-date is before the from-date; with
     *  no from-date it starts on the sheet's today. Returns the periods made, in month order. */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate fromDate, LocalDate to) {
        sheets.load(sheetId, user);
        LocalDate today = sheetStore.findLockedById(sheetId).orElseThrow().getToday();
        LocalDate from = fromDate != null ? fromDate : today;
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date");
        }
        List<Period> existing = periods.findBySheetIdOrderByFromDateAsc(sheetId);
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (existing.stream().anyMatch(p -> p.getName().equals(name) || p.overlaps(first, last))) {
                continue;
            }
            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
            audit.recordChangeOnCommit(sheetId, user, "PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName()
                    + " from=" + added.getFromDate() + " to=" + added.getToDate());
            made.add(added);
        }
        return made;
    }

    /** Close a period, open or soft-closed, fixing its due-total afresh as it is now; refused for a role the
     *  permission matrix does not allow, and when it is already closed. The sheet is locked so no claim in it changes while its total is taken. */
    @Transactional
    public Period close(String sheetId, String user, String name) {
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
        if (!sheet.allows("close", roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
        }
        return closeAndRecord(sheetId, user, period, "");
    }

    /** Soft-close an open period, fixing its due-total and each person's figure for it as they are now, while its
     *  claims can still be changed; refused for a role the permission matrix does not allow to close, and when it is
     *  already closed or soft-closed. */
    @Transactional
    public Period softClose(String sheetId, String user, String name) {
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
        if (!sheet.allows("close", roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (period.isClosed() || period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
        }
        period.softClose(rollup.dueByPersonBetween(sheetId, period.getFromDate(), period.getToDate()));
        Period closed = periods.saveAndFlush(period);
        audit.recordChangeOnCommit(sheetId, user, "PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period="
                + closed.getName() + " total=" + closed.getClosedTotal().toPlainString());
        return closed;
    }

    /** Close, in order of their to-dates, every open period of the sheet whose to-date plus its grace days is
     *  before its today, each exactly as a close by hand. Called with the sheet locked, once its new today is set. */
    @Transactional
    public void closePastGrace(Sheet sheet, String user) {
        if (sheet.getGraceDays() == null) {
            return;
        }
        periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
                .filter(p -> !p.isClosed() && !p.isSoftClosed() && sheet.pastGrace(p.getToDate()))
                .sorted(Comparator.comparing(Period::getToDate))
                .forEach(p -> closeAndRecord(sheet.getId(), user, p, " auto=yes"));
    }

    /** Fix a period's due-total as it is now and record the close; the audit line ends with the suffix given. */
    private Period closeAndRecord(String sheetId, String user, Period period, String suffix) {
        period.close(rollup.dueByPersonBetween(sheetId, period.getFromDate(), period.getToDate()));
        Period closed = periods.saveAndFlush(period);
        BigDecimal total = closed.getClosedTotal();
        audit.recordChangeOnCommit(sheetId, user, "PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + closed.getName()
                + " total=" + total.toPlainString() + suffix);
        return closed;
    }

    /** Reopen a closed or soft-closed period, making its due-total live again; only a role the permission matrix allows may (by
     *  default a steward), and it is refused when the period is open. */
    @Transactional
    public Period reopen(String sheetId, String user, String name) {
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
        if (!sheet.allows("reopen", roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period");
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed");
        }
        period.reopen();
        Period reopened = periods.saveAndFlush(period);
        audit.recordChangeOnCommit(sheetId, user, "PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + reopened.getName());
        return reopened;
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet");
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BiPredicate;
import java.util.function.Function;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.history.SheetState;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The statements taken of people on a sheet. */
@Service
public class StatementService {

    /** What a person's statements come to: how many, and the last one's due-total and date. */
    public record Summary(long personId, int count, String dueTotal, LocalDate takenOn) {
    }

    /** A statement just taken: the person's summary and their claims, newest first, as it left them. */
    public record Taken(Summary summary, List<Claim> claims) {
    }

    private final StatementRepository statements;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateRepository rates;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final Audit audit;
    private final Rollup rollup;
    private final RoleService roles;
    private final SheetHistory history;

    public StatementService(StatementRepository statements, ClaimRepository claims, PersonRepository people,
            RateRepository rates, SheetService sheets, SheetRepository sheetStore, Audit audit, Rollup rollup,
            RoleService roles, SheetHistory history) {
        this.roles = roles;
        this.history = history;
        this.statements = statements;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** The summary of each person on the sheet who has had a statement taken. */
    @Transactional(readOnly = true)
    public List<Summary> list(String sheetId) {
        return summarize(statements.findBySheetIdOrderByIdAsc(sheetId));
    }

    /** The summary of each person who has had one of these statements (in the order taken) taken. */
    public static List<Summary> summarize(List<Statement> taken) {
        Map<Long, Summary> byPerson = new LinkedHashMap<>();
        for (Statement s : taken) {
            Summary before = byPerson.get(s.getPersonId());
            byPerson.put(s.getPersonId(),
                    new Summary(s.getPersonId(), before == null ? 1 : before.count() + 1, s.getDueTotal(), s.getTakenOn()));
        }
        return List.copyOf(byPerson.values());
    }

    /**
     * Take a statement of a person: record their due-total now (with the late charges their overdue claims have gained), bind each of their claims that counts
     * to the figure it has now (its settled figure, else the figure it is bound to, else its amount at
     * its grade's rate in force on its date, not raised to the floor) and leave the rest unbound. A late charge is never
     * bound: it keeps following the sheet's today, and the floor is applied last, to the figure with its charge. The sheet is locked first, so
     * a statement is not taken while a claim on it changes.
     * <p>
     * Taken as of a date ({@code asOf}, on or before the sheet's today), it reads the sheet as it stood at the end of
     * that date (see {@link SheetHistory}): the claims that counted then are bound to their figures as they stood
     * then, that date standing in for the sheet's today in every figure, and the rest are unbound; the statement is
     * dated that date. Refused for a date after the sheet's today, and for a person not on the sheet by then.
     */
    @Transactional
    public Taken take(String sheetId, String user, long personId, LocalDate asOf) {
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
        LocalDate today = sheet.getToday();
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (asOf != null && asOf.isAfter(today)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A statement can be taken as of a date on or before " + today);
        }
        Rollup.Figures before = rollup.of(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, personId);
        Stated stated;
        if (asOf == null) {
            stated = bind(sheet, rates.findBySheetId(sheetId), person, theirs, Function.identity(),
                    person::countsUnbound, theirs);
        } else {
            SheetState then = history.asOf(sheetId, asOf).orElse(null);
            SheetState.PersonState personThen = then == null ? null : then.person(personId).orElse(null);
            if (personThen == null) {
                throw new ResponseStatusException(HttpStatus.CONFLICT,
                        person.getName() + " was not on the sheet by " + asOf);
            }
            Person asThen = personThen.rebuild(sheetId);
            Map<Long, Claim> claimsThen = new HashMap<>();
            then.claims().stream().filter(c -> c.personId() == personId)
                    .forEach(c -> claimsThen.put(c.id(), c.rebuild(sheetId)));
            stated = bind(then.rebuildSheet(sheet, asOf), then.rebuildRates(sheetId), asThen, theirs,
                    c -> claimsThen.get(c.getId()), asThen::counts, claimsThen.values());
        }
        LocalDate takenOn = asOf != null ? asOf : today;
        claims.saveAllAndFlush(theirs);
        statements.saveAndFlush(new Statement(sheetId, personId, stated.dueTotal(), takenOn));
        audit.recordChangeOnCommit(sheetId, user, "STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + stated.dueTotal() + " claims=" + stated.counted() + (asOf == null ? "" : " asof=" + asOf));
        rollup.recordChanges(sheetId, user, before);
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        return new Taken(new Summary(personId, taken.size(), stated.dueTotal(), takenOn), theirs);
    }

    /** What a statement came to: the due-total it records and how many claims it bound. */
    private record Stated(String dueTotal, int counted) {
    }

    /**
     * Bind each of the person's claims ({@code theirs}, as they are now) that counts on the {@code sheet}'s today to its
     * figure and unbind the rest, reading each as it stands on the sheet given ({@code asThen}; none when it was not
     * the person's then), with the person, the rates and the claims that decide its rounding as they stand there.
     */
    private static Stated bind(Sheet sheet, List<Rate> sheetRates, Person person, List<Claim> theirs,
            Function<Claim, Claim> asThen, BiPredicate<Claim, LocalDate> counts, Collection<Claim> roundingClaims) {
        LocalDate today = sheet.getToday();
        Set<String> grades = new HashSet<>(Set.of(person.gradeOn(today)));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean anyDue = false;
        int counted = 0;
        for (Claim claim : theirs) {
            Claim then = asThen.apply(claim);
            if (then == null || !counts.test(then, today) || then.isDeferredOn(today)) {
                claim.unbind();
                continue;
            }
            BigDecimal fixed = then.getSettledDue() != null ? then.getSettledDue() : then.getBoundDue();
            BigDecimal figure = fixed != null || then.isBound() ? fixed
                    : Rate.inForceOn(ratesOf(sheetRates, person.gradeOn(then.getDate())), then.getDate())
                            .map(rate -> ClaimService.liveFigure(then, rate.getRate(),
                                    sheet.roundingFor(ClaimService.roundingDate(then, roundingClaims))))
                            .orElse(null);
            anyDue |= figure != null;
            grades.add(person.gradeOn(then.getDate()));
            total = figure == null ? total
                    : total.add(then.getSettledDue() != null ? figure
                            : ClaimService.floored(then, figure.add(ClaimService.lateCharge(then, figure, sheet, person.gradeOn(then.getDate()))), sheet));
            claim.bind(figure);
            counted++;
        }
        // As on screen: with no rate in force today for their grade on the sheet's today, nor for the grade any
        // of their claims that count is at, and no claim that has a due, the person has no due-total.
        boolean anyRate = grades.stream().anyMatch(g -> Rate.inForceOn(ratesOf(sheetRates, g), today).isPresent());
        return new Stated(!anyRate && !anyDue ? "n/a" : sheet.capped(total).toPlainString(), counted);
    }

    /**
     * A steward cancels a person's last statement: it is removed, and the claims it bound are live again. As each
     * statement binds or unbinds every claim of its person, those are the person's stated claims; a figure a statement
     * before it bound is not restored. Refused for anyone but a steward and for a person with no statement.
     */
    @Transactional
    public Taken cancel(String sheetId, String user, long personId) {
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward cancels a statement");
        }
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        if (taken.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, person.getName() + " has no statement to cancel");
        }
        Rollup.Figures before = rollup.of(sheetId);
        Statement last = taken.get(taken.size() - 1);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, personId);
        theirs.forEach(Claim::unbind);
        claims.saveAllAndFlush(theirs);
        statements.delete(last);
        statements.flush();
        audit.recordChangeOnCommit(sheetId, user, "STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name="
                + person.getName() + " due-total=" + last.getDueTotal());
        rollup.recordChanges(sheetId, user, before);
        List<Statement> left = taken.subList(0, taken.size() - 1);
        Statement previous = left.isEmpty() ? null : left.get(left.size() - 1);
        return new Taken(new Summary(personId, left.size(), previous == null ? null : previous.getDueTotal(),
                previous == null ? null : previous.getTakenOn()), theirs);
    }

    private static List<Rate> ratesOf(List<Rate> sheetRates, String grade) {
        return sheetRates.stream().filter(r -> r.getGrade().equals(grade)).toList();
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A statement taken of a person: their due-total at that moment and the sheet's today then. */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /** The due-total with exactly two decimals, or "n/a" when the person's grade had no rate then. */
    @Column(name = "due_total", nullable = false)
    private String dueTotal;

    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, String dueTotal, LocalDate takenOn) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.dueTotal = dueTotal;
        this.takenOn = takenOn;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public String getDueTotal() {
        return dueTotal;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }
}

