246	     *  records how the figures moved. */
247	    private Sheet record(String id, String user, String key, LocalDate from, String value, boolean movesFigures) {
248	        load(id, user);
249	        Sheet sheet = sheets.findLockedById(id).orElseThrow();
250	        Rollup.Figures before = movesFigures ? rollup.of(id) : null;
251	        sheet.record(key, from != null ? from : sheet.getToday(), value);
252	        Sheet saved = sheets.saveAndFlush(sheet);
