277	/**
278	 * Refuses every change asked for on an archived sheet: any request on it other than a read is refused before it
279	 * reaches its handler, so it writes nothing. Loading the sheet and the bulk actions (taken with every selected item
280	 * refused) are left to their handlers; see {@link ArchiveGuardConfig}.
281	 */
282	@Component
283	public class ArchiveGuard implements HandlerInterceptor {
284	
285	    private final SheetService sheets;
286	
287	    public ArchiveGuard(SheetService sheets) {
288	        this.sheets = sheets;
289	    }
290	
291	    @Override
292	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
293	        String method = request.getMethod();
294	        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
295	            return true;
296	        }
297	        String sheetId = sheetId(request);
298	        if (sheetId != null && sheets.isArchived(sheetId)) {
299	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived: nothing on it can change");
300	        }
301	        return true;
302	    }
303	
304	    @SuppressWarnings("unchecked")
305	    private static String sheetId(HttpServletRequest request) {
306	        Object vars = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
307	        if (!(vars instanceof Map<?, ?> map)) {
308	            return null;
309	        }
310	        Map<String, String> path = (Map<String, String>) map;
311	        return path.containsKey("sheetId") ? path.get("sheetId") : path.get("id");
312	    }
313	}
