386	/**
387	 * A sheet's history: after each change, what the sheet holds is kept under the sheet's today, replacing what was kept
388	 * under that day before. The sheet as it stood at the end of a date is then the last kept under a day on or before
389	 * it: every change made while the sheet's today was on or before that date, and none made later.
390	 */
391	@Service
392	public class SheetHistory {
393	
394	    /** The request header naming the date a user's screen shows the sheet as of (an ISO date): while it is sent, every
395	     *  read of the sheet answers as the sheet stood at the end of that date, that date standing in for its today, and
396	     *  every change is refused (see {@link AsOfGuard}). */
397	    public static final String AS_OF_HEADER = "X-As-Of";
398	
399	    private final SheetSnapshotRepository snapshots;
400	    private final SheetRepository sheets;
401	    private final RateRepository rates;
402	    private final PersonRepository people;
403	    private final ClaimRepository claims;
404	    private final PeriodRepository periods;
405	    private final StatementRepository statements;
406	    private final PatronRepository patrons;
407	    private final WatchRepository watches;
408	    private final RoleRepository roles;
409	    private final DelegationRepository delegations;
410	    private final HolidayRepository holidays;
411	    private final JsonMapper json;
412	
413	    public SheetHistory(SheetSnapshotRepository snapshots, SheetRepository sheets, RateRepository rates,
414	            PersonRepository people, ClaimRepository claims, PeriodRepository periods, StatementRepository statements,
415	            PatronRepository patrons, WatchRepository watches, RoleRepository roles, DelegationRepository delegations,
416	            HolidayRepository holidays, JsonMapper json) {
417	        this.snapshots = snapshots;
418	        this.sheets = sheets;
419	        this.rates = rates;
420	        this.people = people;
421	        this.claims = claims;
422	        this.periods = periods;
423	        this.statements = statements;
424	        this.patrons = patrons;
425	        this.watches = watches;
426	        this.roles = roles;
427	        this.delegations = delegations;
428	        this.holidays = holidays;
429	        this.json = json;
430	    }
431	
432	    /** Keep what the sheet holds once the change being made is done: just before the current transaction commits,
433	     *  once however many changes it records; outside a transaction, at once. */
434	    public void keepOnCommit(String sheetId) {
435	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
436	            keep(sheetId);
437	            return;
438	        }
439	        String key = SheetHistory.class.getName() + ":" + sheetId;
440	        if (TransactionSynchronizationManager.hasResource(key)) {
441	            return;
442	        }
443	        TransactionSynchronizationManager.bindResource(key, Boolean.TRUE);
444	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
445	            @Override
446	            public void beforeCommit(boolean readOnly) {
447	                if (!readOnly) {
448	                    keep(sheetId);
449	                }
450	            }
451	
452	            @Override
453	            public void afterCompletion(int status) {
454	                TransactionSynchronizationManager.unbindResourceIfPossible(key);
455	            }
456	        });
457	    }
458	
459	    /** Keep what the sheet holds now under its today. */
460	    @Transactional
461	    public void keep(String sheetId) {
462	        Sheet sheet = sheets.findById(sheetId).orElse(null);
463	        if (sheet == null) {
464	            return;
465	        }
466	        List<Rate> sheetRates = rates.findBySheetId(sheetId);
467	        List<Person> sheetPeople = people.findBySheetIdOrderByIdAsc(sheetId);
468	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
469	        Map<String, List<Long>> watched = new TreeMap<>();
470	        watches.findBySheetIdOrderByIdAsc(sheetId).forEach(w ->
471	                watched.computeIfAbsent(w.getUserName(), u -> new ArrayList<>()).add(w.getPersonId()));
472	        SheetState.Views views = new SheetState.Views(
473	                sheetPeople.stream().map(p -> PersonView.of(p, sheet.getToday())).toList(),
474	                sheetClaims.stream().map(ClaimView::of).map(SheetHistory::unlocked).toList(),
475	                sheetRates.stream().sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate.BY_FROM))
476	                        .map(RateView::of).toList(),
477	                periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().map(PeriodView::of).toList(),
478	                StatementService.summarize(statements.findBySheetIdOrderByIdAsc(sheetId)).stream()
479	                        .map(SummaryView::of).toList(),
480	                patrons.findBySheetIdOrderByIdAsc(sheetId).stream().map(PatronView::of).toList(),
481	                watched,
482	                roles.findBySheetIdOrderByUserName(sheetId).stream().map(RoleView::of).toList(),
483	                delegations.findBySheetIdOrderByIdAsc(sheetId).stream().map(DelegationView::of).toList(),
484	                holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(HolidayView::of).toList());
485	        SheetState state = SheetState.of(sheet, sheetRates, sheetPeople, sheetClaims, views);
486	        snapshots.deleteBySheetIdAndAsOf(sheetId, sheet.getToday());
487	        snapshots.saveAndFlush(new SheetSnapshot(sheetId, sheet.getToday(), json.writeValueAsString(state)));
488	    }
489	
490	    /** The sheet as it stood at the end of a date; empty when no change was made on it by then. */
491	    @Transactional(readOnly = true)
492	    public Optional<SheetState> asOf(String sheetId, LocalDate date) {
493	        return snapshots.findFirstBySheetIdAndAsOfLessThanEqualOrderByAsOfDescIdDesc(sheetId, date)
494	                .map(s -> json.readValue(s.getState(), SheetState.class));
495	    }
496	
497	    /** The claim as kept: no one's editor lock is part of what the sheet held. */
498	    private static ClaimView unlocked(ClaimView c) {
499	        return new ClaimView(c.id(), c.personId(), c.amount(), c.date(), c.note(), c.status(), c.number(),
500	                c.settledDue(), c.openedBy(), c.stated(), c.statedDue(), c.corrects(), c.dueBy(), c.deferredUntil(),
501	                c.log(), c.proofs(), c.splitFrom(), null, c.lateEntry(), c.remindedOn(), c.ref(), c.tags(),
502	                c.voidReason(), c.comments(), c.editedBy(), c.batch());
503	    }
504	
505	    /** The lists the screen reads of the sheet as it stood at the end of a date; none when no change was made on it
506	     *  by then. */
507	    @Transactional(readOnly = true)
508	    public SheetState.Views viewsAsOf(String sheetId, LocalDate date) {
509	        return asOf(sheetId, date).map(SheetState::views).orElse(SheetState.Views.NONE);
510	    }
511	
512	    /** The people as the screen read them at the end of a date, each with the grade in force on it. */
513	    @Transactional(readOnly = true)
514	    public List<PersonView> peopleAsOf(String sheetId, LocalDate date) {
515	        return asOf(sheetId, date).map(s -> s.people(sheetId, date)).orElse(List.of());
516	    }
517	
518	    /** The sheet as it stood at the end of a date, unsaved, with that date standing in for its today: as it was
519	     *  started when no change was made on it by then. */
520	    @Transactional(readOnly = true)
521	    public Sheet sheetAsOf(Sheet live, LocalDate date) {
522	        return asOf(live.getId(), date).map(s -> s.rebuildSheet(live, date))
523	                .orElseGet(() -> new Sheet(live.getId(), live.getCreatedBy(), live.getCreatedAt(), date));
524	    }
525	}
