570	    /**
571	     * Add a DRAFT claim per line of {@code text} (name,amount,date,note; the note may hold commas, a blank date
572	     * takes the sheet's entry date while set, else its today, the note may be absent), in order, for the person on the sheet whose name matches
573	     * (trimmed, ignoring case). Each line is checked by exactly the claim form's rules; one change: when any line
574	     * is refused, nothing is added and nothing is recorded. Blank lines are skipped; a paste with no lines is
575	     * refused. A note ending in {@code " #<reference>"} gives the claim that external reference, which is not part of
576	     * the note; a reference used on the sheet or on an earlier line, without regard to case, refuses the paste.
577	     */
578	    @Transactional
579	    public List<Claim> paste(String sheetId, String user, String text) {
580	        List<Line> lines = new ArrayList<>();
581	        Set<String> refs = new HashSet<>();
582	        for (String raw : text.split("\\r?\\n")) {
583	            if (!raw.isBlank()) {
584	                Line line = read(sheetId, raw);
585	                if (line.ref() != null && !refs.add(line.ref().toLowerCase(Locale.ROOT))) {
586	                    throw ClaimService.refUsed(line.ref());
587	                }
588	                lines.add(line);
589	            }
590	        }
591	        if (lines.isEmpty()) {
592	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line");
593	        }
594	        List<Claim> added = new ArrayList<>();
595	        for (Line line : lines) {
596	            added.add(claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(), null,
597	                    line.ref()));
598	        }
599	        return added;
600	    }
601	
602	    private Line read(String sheetId, String raw) {
603	        String[] fields = raw.split(",", 4);
604	        if (fields.length < 2) {
605	            throw refused("Each line needs at least a name and an amount");
606	        }
607	        String name = fields[0].trim();
608	        if (name.isEmpty()) {
609	            throw refused("Each line needs a name");
610	        }
611	        Person person = people.findBySheetIdAndNameIgnoreCase(sheetId, name)
612	                .orElseThrow(() -> refused("No one named " + name + " is on this sheet"));
613	        String amount = fields[1].trim();
614	        if (!AMOUNT.matcher(amount).matches()) {
615	            throw refused("An amount takes up to two decimals");
616	        }
617	        LocalDate date = null;
618	        String dateText = fields.length > 2 ? fields[2].trim() : "";
619	        if (!dateText.isEmpty()) {
620	            try {
621	                date = LocalDate.parse(dateText);
622	            } catch (DateTimeParseException e) {
623	                throw refused("A date is written yyyy-mm-dd");
624	            }
625	        }
626	        String note = fields.length > 3 ? fields[3] : "";
627	        if (note.length() > NOTE_MAX) {
628	            throw refused("A note is at most " + NOTE_MAX + " characters");
629	        }
630	        String ref = null;
631	        String trimmed = note.trim();
632	        int hash = trimmed.lastIndexOf(" #");
633	        if (hash >= 0 && !trimmed.substring(hash + 2).isBlank()) {
634	            ref = ClaimService.refOf(trimmed.substring(hash + 2));
635	            note = trimmed.substring(0, hash);
636	        }
637	        if (ref != null && ref.length() > REF_MAX) {
638	            throw refused("A reference is at most " + REF_MAX + " characters");
639	        }
640	        return new Line(person, new BigDecimal(amount), date, note, ref);
641	    }
642	
643	    private static ResponseStatusException refused(String reason) {
644	        return new ResponseStatusException(HttpStatus.BAD_REQUEST, reason);
645	    }
646	}
